prompt --application/shared_components/logic/application_processes/get_profile_photo
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(9913500000000001)
,p_process_sequence=>1
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'GET_PROFILE_PHOTO'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(100);',
'    l_filename  VARCHAR2(255);',
'    l_person_id NUMBER;',
'    l_type      VARCHAR2(15);',
'BEGIN',
'    BEGIN',
'        SELECT LinkedPersonID, UPPER(TRIM(LinkedPersonType))',
'          INTO l_person_id, l_type',
'          FROM USER_ACCOUNT',
'         WHERE UPPER(Username) = UPPER(:APP_USER)',
'           AND IsActive = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            sys.owa_util.status_line(404, ''Not Found'', TRUE);',
'            apex_application.stop_apex_engine;',
'            RETURN;',
'    END;',
'',
'    BEGIN',
'        IF l_type = ''TRUSTEE'' AND l_person_id IS NOT NULL THEN',
'            SELECT ProfilePhoto, ProfilePhotoMimeType, ProfilePhotoFileName',
'              INTO l_blob, l_mime, l_filename',
'              FROM TRUSTEE',
'             WHERE TrusteeID = l_person_id;',
'        ELSIF l_type = ''BENEFICIARY'' AND l_person_id IS NOT NULL THEN',
'            SELECT ProfilePhoto, ProfilePhotoMimeType, ProfilePhotoFileName',
'              INTO l_blob, l_mime, l_filename',
'              FROM BENEFICIARY',
'             WHERE BeneficiaryID = l_person_id;',
'        ELSIF l_type = ''TRUSTOR'' AND l_person_id IS NOT NULL THEN',
'            SELECT ProfilePhoto, ProfilePhotoMimeType, ProfilePhotoFileName',
'              INTO l_blob, l_mime, l_filename',
'              FROM TRUSTOR',
'             WHERE TrustorID = l_person_id;',
'        ELSE',
'            SELECT ProfilePhoto, ProfilePhotoMimeType, ProfilePhotoFileName',
'              INTO l_blob, l_mime, l_filename',
'              FROM USER_ACCOUNT',
'             WHERE UPPER(Username) = UPPER(:APP_USER);',
'        END IF;',
'    EXCEPTION',
'        WHEN OTHERS THEN',
'            l_blob := NULL;',
'    END;',
'',
'    IF l_blob IS NULL OR DBMS_LOB.GETLENGTH(l_blob) = 0 THEN',
'        BEGIN',
'            SELECT ProfilePhoto, ProfilePhotoMimeType, ProfilePhotoFileName',
'              INTO l_blob, l_mime, l_filename',
'              FROM USER_ACCOUNT',
'             WHERE UPPER(Username) = UPPER(:APP_USER);',
'        EXCEPTION',
'            WHEN OTHERS THEN',
'                l_blob := NULL;',
'        END;',
'    END IF;',
'',
'    IF l_blob IS NULL OR DBMS_LOB.GETLENGTH(l_blob) = 0 THEN',
'        sys.owa_util.status_line(404, ''Not Found'', TRUE);',
'        apex_application.stop_apex_engine;',
'        RETURN;',
'    END IF;',
'',
'    sys.htp.init;',
'    sys.owa_util.mime_header(NVL(l_mime, ''image/jpeg''), FALSE);',
'    sys.htp.p(''Content-Length: '' || DBMS_LOB.GETLENGTH(l_blob));',
'    sys.htp.p(''Content-Disposition: inline; filename="'' ||',
'              REPLACE(NVL(l_filename, ''avatar.jpg''), ''"'', '''') || ''"'');',
'    sys.htp.p(''Cache-Control: private, max-age=60'');',
'    sys.owa_util.http_header_close;',
'    sys.wpg_docload.download_file(l_blob);',
'    apex_application.stop_apex_engine;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/set_user_avatar_url
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(9913500000000002)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SET_USER_AVATAR_URL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :APP_USER IS NULL OR UPPER(:APP_USER) IN (''NOBODY'',''HTMLDB_PUBLIC_USER'',''APEX_PUBLIC_USER'') THEN',
'        :G_USER_AVATAR_URL := NULL;',
'        RETURN;',
'    END IF;',
'',
'    IF :G_AVATAR_TS IS NULL THEN',
'        :G_AVATAR_TS := TO_CHAR(SYSTIMESTAMP, ''YYYYMMDDHH24MISS'');',
'    END IF;',
'',
'    :G_USER_AVATAR_URL :=',
'           ''f?p='' || :APP_ID || '':0:'' || :APP_SESSION',
'        || '':APPLICATION_PROCESS=GET_PROFILE_PHOTO:::G_AVATAR_TS,''',
'        || :G_AVATAR_TS;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
