wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9012500000000001)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Redirect by role'
,p_static_id=>'redirect-by-role'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_type VARCHAR2(30);',
'    l_role VARCHAR2(30);',
'    l_page NUMBER;',
'BEGIN',
'    SELECT u.LinkedPersonType, r.RoleName',
'      INTO l_type, l_role',
'      FROM USER_ACCOUNT u',
'      JOIN ROLE r ON r.RoleID = u.RoleID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND u.IsActive = 1',
'       AND ROWNUM = 1;',
'    IF l_role = ''AUDITOR'' THEN',
'      l_page := 28;',
'    ELSE',
'      l_page := CASE l_type',
'                  WHEN ''ADMIN'' THEN 10',
'                  WHEN ''TRUSTEE'' THEN 11',
'                  WHEN ''BENEFICIARY'' THEN 12',
'                  WHEN ''TRUSTOR'' THEN 13',
'                  ELSE 10',
'                END;',
'    END IF;',
'    apex_util.redirect_url(p_url => apex_page.get_url(p_page => l_page));',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9012500000000001
,p_created_on=>wwv_flow_imp.dz('20260806103000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806103000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
end;
