,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_trusts        NUMBER;',
'    l_assets        NUMBER;',
'    l_pending       NUMBER;',
'    l_unread        NUMBER;',
'BEGIN',
'    SELECT COUNT(*) INTO l_trusts FROM TRUST;',
'    SELECT COUNT(*) INTO l_assets FROM ASSET;',
'    SELECT COUNT(*) INTO l_pending FROM DISTRIBUTION WHERE Status = ''PENDING'';',
'    SELECT COUNT(*) INTO l_unread',
'      FROM NOTIFICATION n',
'      JOIN USER_ACCOUNT u ON u.UserID = n.UserID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND n.IsRead = 0;',
'',
'    htp.p(''<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:20px 0;padding:0 15px;">'');',
