wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9913500000000001)
,p_plug_name=>'Live Charts'
,p_static_id=>'admin-live-charts'
,p_title=>'Live Charts (auto-updates from database)'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_plug_display_point=>'BODY'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_max NUMBER := 1;',
'    PROCEDURE bar(p_label VARCHAR2, p_value NUMBER, p_max NUMBER) IS',
'        l_pct NUMBER;',
'        l_w   NUMBER;',
'    BEGIN',
'        l_pct := CASE WHEN p_max <= 0 THEN 0 ELSE ROUND((p_value / p_max) * 100) END;',
'        l_w := GREATEST(l_pct, CASE WHEN p_value > 0 THEN 4 ELSE 0 END);',
'        htp.p(''<div style="margin:10px 0;">'');',
'        htp.p(''<div style="display:flex;justify-content:space-between;font-size:13px;color:#334155;margin-bottom:4px;"><span>''||',
'              apex_escape.html(p_label)||''</span><strong>''||p_value||''</strong></div>'');',
'        htp.p(''<div style="background:#e2e8f0;border-radius:6px;height:14px;overflow:hidden;">'');',
'        htp.p(''<div style="width:''||l_w||''%;height:14px;background:#0f766e;border-radius:6px;"></div>'');',
'        htp.p(''</div></div>'');',
'    END;',
'BEGIN',
'    htp.p(''<div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:8px 4px;">'');',
'',
'    -- Chart 1: Trusts by status (live query)',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:16px;">'');',
'    htp.p(''<h3 style="margin:0 0 12px 0;font-size:15px;color:#0f172a;">Trusts by Status</h3>'');',
'    SELECT NVL(MAX(cnt),1) INTO l_max FROM (',
'        SELECT COUNT(*) cnt FROM TRUST GROUP BY Status',
'    );',
'    FOR r IN (',
'        SELECT NVL(Status,''UNKNOWN'') AS label, COUNT(*) AS cnt',
'          FROM TRUST',
'         GROUP BY Status',
'         ORDER BY COUNT(*) DESC, Status',
'    ) LOOP',
'        bar(r.label, r.cnt, l_max);',
'    END LOOP;',
'    htp.p(''<p style="margin:12px 0 0 0;font-size:11px;color:#94a3b8;">Updates automatically when trusts change.</p>'');',
'    htp.p(''</div>'');',
'',
'    -- Chart 2: Distributions by status (live query)',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:16px;">'');',
'    htp.p(''<h3 style="margin:0 0 12px 0;font-size:15px;color:#0f172a;">Distributions by Status</h3>'');',
'    SELECT NVL(MAX(cnt),1) INTO l_max FROM (',
'        SELECT COUNT(*) cnt FROM DISTRIBUTION GROUP BY Status',
'    );',
'    FOR r IN (',
'        SELECT NVL(Status,''UNKNOWN'') AS label, COUNT(*) AS cnt',
'          FROM DISTRIBUTION',
'         GROUP BY Status',
'         ORDER BY COUNT(*) DESC, Status',
'    ) LOOP',
'        bar(r.label, r.cnt, l_max);',
'    END LOOP;',
'    htp.p(''<p style="margin:12px 0 0 0;font-size:11px;color:#94a3b8;">Updates automatically when distributions change.</p>'');',
'    htp.p(''</div>'');',
'',
'    htp.p(''</div>'');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20260806120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
end;
