wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(7430930061837236)
,p_plug_name=>'Trustee KPIs'
,p_static_id=>'trustee-kpis'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>3372714138756020509
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_trusts   NUMBER;',
'    l_pending  NUMBER;',
'    l_assets   NUMBER;',
'    l_unread   NUMBER;',
'BEGIN',
'    SELECT COUNT(DISTINCT t.TrustID) INTO l_trusts',
'      FROM TRUST t',
'      JOIN TRUST_TRUSTEE tt ON t.TrustID = tt.TrustID',
'      JOIN TRUSTEE te ON tt.TrusteeID = te.TrusteeID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = te.TrusteeID AND u.LinkedPersonType = ''TRUSTEE''',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER);',
'',
'    SELECT COUNT(*) INTO l_pending',
'      FROM DISTRIBUTION d',
'      JOIN ASSET a ON d.AssetID = a.AssetID',
'      JOIN TRUST_TRUSTEE tt ON a.TrustID = tt.TrustID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = tt.TrusteeID AND u.LinkedPersonType = ''TRUSTEE''',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND d.Status = ''PENDING'';',
'',
'    SELECT COUNT(*) INTO l_assets',
'      FROM ASSET a',
'      JOIN TRUST_TRUSTEE tt ON a.TrustID = tt.TrustID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = tt.TrusteeID AND u.LinkedPersonType = ''TRUSTEE''',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER);',
'',
'    SELECT COUNT(*) INTO l_unread',
'      FROM NOTIFICATION n',
'      JOIN USER_ACCOUNT u ON u.UserID = n.UserID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND n.IsRead = 0;',
'',
'    htp.p(''<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin:20px 0;padding:0 15px;">'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_trusts||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">My Trusts</p></div>'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_pending||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Pending Approvals</p></div>'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_assets||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Total Assets</p></div>'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_unread||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Notifications</p></div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20260805114832Z')
