,p_plug_name=>'New'
,p_static_id=>'new_2'
,p_title=>'Pending Approvals'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    d.DistributionID,',
'    t.TrustName,',
'    b.Name AS Beneficiary,',
'    d.AmountRequested,',
'    d.DateRequested,',
'    (SELECT COUNT(*) FROM APPROVAL ',
'     WHERE DistributionID = d.DistributionID ',
'     AND Decision = ''APPROVED'') AS ApprovalsCount',
'FROM DISTRIBUTION d',
'JOIN ASSET a ON d.AssetID = a.AssetID',
'JOIN TRUST t ON a.TrustID = t.TrustID',
'JOIN BENEFICIARY b ON d.BeneficiaryID = b.BeneficiaryID',
'JOIN TRUST_TRUSTEE tt ON t.TrustID = tt.TrustID',
'JOIN TRUSTEE te ON tt.TrusteeID = te.TrusteeID',
'JOIN USER_ACCOUNT u ON u.LinkedPersonID = te.TrusteeID',
'                  AND u.LinkedPersonType = ''TRUSTEE''',
'WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'AND d.Status = ''PENDING''',
'ORDER BY d.DateRequested'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
