wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9901200000000001)
,p_plug_name=>'Beneficiary Overview'
,p_static_id=>'beneficiary-overview'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_pending NUMBER;',
'    l_paid    NUMBER;',
'    l_unread  NUMBER;',
'BEGIN',
'    SELECT COUNT(*) INTO l_pending',
'      FROM DISTRIBUTION d',
'      JOIN BENEFICIARY b ON b.BeneficiaryID = d.BeneficiaryID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = b.BeneficiaryID AND u.LinkedPersonType = ''BENEFICIARY''',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND d.Status IN (''PENDING'',''APPROVED'');',
'',
'    SELECT NVL(SUM(d.AmountRequested),0) INTO l_paid',
'      FROM DISTRIBUTION d',
'      JOIN BENEFICIARY b ON b.BeneficiaryID = d.BeneficiaryID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = b.BeneficiaryID AND u.LinkedPersonType = ''BENEFICIARY''',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND d.Status = ''EXECUTED'';',
'',
'    SELECT COUNT(*) INTO l_unread',
'      FROM NOTIFICATION n',
'      JOIN USER_ACCOUNT u ON u.UserID = n.UserID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND n.IsRead = 0;',
'',
'    htp.p(''<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:20px 0;padding:0 15px;">'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_pending||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Open Distributions</p></div>'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600;font-size:28px">UGX ''||TO_CHAR(l_paid,''999G999G999G999'')||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Total Received</p></div>'');',
'    htp.p(''<div style="background:#ffffff;border:1px solid #e2e8f0;color:#0f172a;padding:20px;border-radius:10px;text-align:center;box-shadow:0 1px 2px rgba(15,23,42,0.04)"><h2 style="margin:0;font-size:32px;color:#0f766e;font-weight:600">''||l_unread||''</h2><p style="margin:8px 0 0 0;font-size:13px;color:#64748b">Unread Notifications</p></div>'');',
'    htp.p(''<div style="grid-column:1/-1;"><a href="f?p=&APP_ID.:33:&APP_SESSION.">Open Notifications</a></div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20260806060000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806060000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
