 p_id=>wwv_flow_imp.id(9913600000000002)
,p_plug_name=>'Trustor Overview'
,p_static_id=>'trustor-overview'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>4502917002193490937
,p_plug_display_sequence=>20
,p_plug_display_point=>'BODY'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_trusts NUMBER;',
'    l_bens   NUMBER;',
'    l_assets NUMBER;',
'    l_txns   NUMBER;',
'    l_paid   NUMBER;',
'BEGIN',
'    SELECT COUNT(*) INTO l_trusts',
'      FROM TRUST t',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = t.TrustorID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND u.LinkedPersonType = ''TRUSTOR'';',
'',
'    SELECT COUNT(DISTINCT tb.BeneficiaryID) INTO l_bens',
'      FROM TRUST_BENEFICIARY tb',
'      JOIN TRUST t ON t.TrustID = tb.TrustID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = t.TrustorID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND u.LinkedPersonType = ''TRUSTOR'';',
'',
'    SELECT COUNT(*) INTO l_assets',
'      FROM ASSET a',
'      JOIN TRUST t ON t.TrustID = a.TrustID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = t.TrustorID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND u.LinkedPersonType = ''TRUSTOR'';',
'',
'    SELECT COUNT(*), NVL(SUM(CASE WHEN d.Status = ''EXECUTED'' THEN d.AmountRequested ELSE 0 END),0)',
'      INTO l_txns, l_paid',
'      FROM DISTRIBUTION d',
'      JOIN ASSET a ON a.AssetID = d.AssetID',
'      JOIN TRUST t ON t.TrustID = a.TrustID',
'      JOIN USER_ACCOUNT u ON u.LinkedPersonID = t.TrustorID',
'     WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'       AND u.LinkedPersonType = ''TRUSTOR'';',
'',
'    htp.p(''<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;padding:8px 4px;">'');',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;text-align:center;"><h2 style="margin:0;color:#0f766e;">''||l_trusts||''</h2><p style="margin:6px 0 0 0;color:#64748b;font-size:13px;">My Trusts</p></div>'');',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;text-align:center;"><h2 style="margin:0;color:#0f766e;">''||l_bens||''</h2><p style="margin:6px 0 0 0;color:#64748b;font-size:13px;">Beneficiaries</p></div>'');',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;text-align:center;"><h2 style="margin:0;color:#0f766e;">''||l_txns||''</h2><p style="margin:6px 0 0 0;color:#64748b;font-size:13px;">Distributions</p></div>'');',
'    htp.p(''<div style="background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;text-align:center;"><h2 style="margin:0;color:#0f766e;font-size:22px;">UGX ''||TRIM(TO_CHAR(l_paid,''999G999G999G999''))||''</h2><p style="margin:6px 0 0 0;color:#64748b;font-size:13px;">Paid Out</p></div>'');',
'    htp.p(''<div style="grid-column:1/-1;padding:12px 14px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;color:#334155;font-size:13px;">As the <strong>Trustor</strong>, you can view your trusts, beneficiaries, assets, and all distribution transactions made to beneficiaries. Day-to-day management is done by Trustees.</div>'');',
'    htp.p(''</div>'');',
'END;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_created_on=>wwv_flow_imp.dz('20260806123000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806123000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
