,p_plug_name=>'Distributions to Beneficiaries'
,p_static_id=>'trustor-distributions'
,p_title=>'Distributions to Beneficiaries'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>50
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT d.DistributionID,',
'       t.TrustName,',
'       b.Name AS BeneficiaryName,',
'       a.AssetName,',
'       d.AmountRequested,',
'       d.DateRequested,',
'       d.Status,',
'       te.Name AS InitiatedBy',
'  FROM DISTRIBUTION d',
'  JOIN ASSET a ON a.AssetID = d.AssetID',
'  JOIN TRUST t ON t.TrustID = a.TrustID',
'  JOIN BENEFICIARY b ON b.BeneficiaryID = d.BeneficiaryID',
'  JOIN TRUSTEE te ON te.TrusteeID = d.InitiatedByTrusteeID',
'  JOIN USER_ACCOUNT u ON u.LinkedPersonID = t.TrustorID',
' WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'   AND u.LinkedPersonType = ''TRUSTOR''',
' ORDER BY d.DateRequested DESC'))
