wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9914400000000002)
,p_process_sequence=>3
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Validate LinkedPersonID exists'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_cnt NUMBER := 0;',
'  l_role VARCHAR2(30);',
'  l_type VARCHAR2(30) := UPPER(TRIM(:P27_LINKEDPERSONTYPE));',
'BEGIN',
'  IF :P27_LINKEDPERSONID IS NULL OR l_type IS NULL THEN',
'    RAISE_APPLICATION_ERROR(-20027, ''Person Type and Linked Person ID are required.'');',
'  END IF;',
'  IF l_type = ''ADMIN'' THEN',
'    l_cnt := 1; -- admin may link to any admin person id / self',
'  ELSIF l_type = ''TRUSTOR'' THEN',
'    SELECT COUNT(*) INTO l_cnt FROM TRUSTOR WHERE TrustorID = :P27_LINKEDPERSONID;',
'  ELSIF l_type = ''TRUSTEE'' THEN',
'    SELECT COUNT(*) INTO l_cnt FROM TRUSTEE WHERE TrusteeID = :P27_LINKEDPERSONID;',
'  ELSIF l_type = ''BENEFICIARY'' THEN',
'    SELECT COUNT(*) INTO l_cnt FROM BENEFICIARY WHERE BeneficiaryID = :P27_LINKEDPERSONID;',
'  ELSE',
'    RAISE_APPLICATION_ERROR(-20028, ''Invalid Person Type. Use ADMIN, TRUSTOR, TRUSTEE, or BENEFICIARY.'');',
'  END IF;',
'  IF l_type <> ''ADMIN'' AND l_cnt = 0 THEN',
'    RAISE_APPLICATION_ERROR(-20029,',
'      ''Linked Person ID '' || :P27_LINKEDPERSONID || '' does not exist in '' || l_type || '' table.'');',
'  END IF;',
'  BEGIN',
'    SELECT r.RoleName INTO l_role FROM ROLE r WHERE r.RoleID = :P27_ROLEID;',
'    IF l_role NOT IN (''AUDITOR'') AND l_role <> l_type AND NOT (l_role = ''ADMIN'' AND l_type = ''ADMIN'') THEN',
'      IF NOT (l_role = l_type) THEN',
'        apex_application.g_print_success_message :=',
'          NVL(apex_application.g_print_success_message,'''') ||',
'          '' Warning: Role '' || l_role || '' does not match Person Type '' || l_type || ''.'';',
'      END IF;',
'    END IF;',
'  EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'CREATE,SAVE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>9914400000000002
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9914400000000001)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Hash password on save'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_hash VARCHAR2(64);',
'BEGIN',
'  IF :P27_PASSWORDHASH IS NOT NULL AND LENGTH(TRIM(:P27_PASSWORDHASH)) <> 64 THEN',
'    -- STANDARD_HASH is SQL-only; calling it directly from PL/SQL raises PLS-00201.',
'    SELECT LOWER(RAWTOHEX(STANDARD_HASH(TRIM(:P27_PASSWORDHASH), ''SHA256'')))',
'      INTO l_hash',
'      FROM DUAL;',
'    :P27_PASSWORDHASH := l_hash;',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9914400000000001
,p_created_on=>wwv_flow_imp.dz('20260806132000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806132000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
