,p_prompt=>'Asset'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT a.AssetName || '' (UGX '' || TO_CHAR(a.EstimatedValue,''999G999G999G999'') || '')'' AS d,',
'       a.AssetID AS r',
'  FROM ASSET a',
'  JOIN TRUST_TRUSTEE tt ON tt.TrustID = a.TrustID',
'  JOIN USER_ACCOUNT u ON u.LinkedPersonID = tt.TrusteeID',
'                     AND u.LinkedPersonType = ''TRUSTEE''',
' WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'   AND a.Status IN (''AVAILABLE'',''PARTIALLY_DISTRIBUTED'')',
' ORDER BY a.AssetName'))
,p_lov_display_null=>'YES'
