wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913100000000029)
,p_process_sequence=>5
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Validate distribution amount against balance'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_trust_id NUMBER;',
'  l_bal      NUMBER;',
'  l_asset_val NUMBER;',
'  l_used     NUMBER;',
'  l_avail    NUMBER;',
'BEGIN',
'  SELECT TrustID, EstimatedValue INTO l_trust_id, l_asset_val',
'    FROM ASSET WHERE AssetID = :P31_ASSETID;',
'  l_bal := PKG_TRUST_MGMT.get_trust_balance(l_trust_id);',
'  SELECT NVL(SUM(AmountRequested),0) INTO l_used',
'    FROM DISTRIBUTION',
'   WHERE AssetID = :P31_ASSETID',
'     AND Status IN (''PENDING'',''APPROVED'',''EXECUTED'');',
'  l_avail := LEAST(l_bal, l_asset_val - l_used);',
'  IF :P31_AMOUNT IS NULL OR :P31_AMOUNT <= 0 THEN',
'    RAISE_APPLICATION_ERROR(-20031, ''Amount must be greater than zero.'');',
'  END IF;',
'  IF :P31_AMOUNT > l_avail THEN',
'    RAISE_APPLICATION_ERROR(-20032,',
'      ''Amount exceeds available balance. Available: UGX '' ||',
'      TO_CHAR(l_avail,''999G999G999G999D00'') ||',
'      '' (trust balance UGX '' || TO_CHAR(l_bal,''999G999G999G999D00'') || '').'');',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913100000000020)
,p_internal_uid=>9913100000000029
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
