,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_id NUMBER;',
'BEGIN',
'    PKG_TRUST_MGMT.request_distribution(',
'        p_asset_id         => :P31_ASSETID,',
'        p_beneficiary_id   => :P31_BENEFICIARYID,',
'        p_amount_requested => :P31_AMOUNT,',
'        p_distribution_id  => l_id',
'    );',
'    apex_application.g_print_success_message :=',
'        ''Distribution request #'' || l_id || '' submitted. Other trustees have been notified.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913100000000020)
