'SELECT d.DistributionID,',
'       t.TrustName,',
'       a.AssetName,',
'       b.Name AS Beneficiary,',
'       d.AmountRequested,',
'       d.DateRequested,',
'       d.Status,',
'       tr.Name AS InitiatedBy,',
'       (SELECT COUNT(*) FROM APPROVAL ap',
'         WHERE ap.DistributionID = d.DistributionID',
'           AND ap.Decision = ''APPROVED'') AS ApprovalsSoFar',
'  FROM DISTRIBUTION d',
'  JOIN ASSET a ON a.AssetID = d.AssetID',
'  JOIN TRUST t ON t.TrustID = a.TrustID',
'  JOIN BENEFICIARY b ON b.BeneficiaryID = d.BeneficiaryID',
'  JOIN TRUSTEE tr ON tr.TrusteeID = d.InitiatedByTrusteeID',
' WHERE d.DistributionID = :P32_DISTRIBUTIONID'))
