 p_id=>wwv_flow_imp.id(9913200000000089)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load existing payment receipt info'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P32_DISTRIBUTIONID IS NOT NULL THEN',
'    SELECT NVL(PaymentReceiptFileName, ''(none uploaded)'')',
'      INTO :P32_RECEIPT_INFO',
'      FROM DISTRIBUTION WHERE DistributionID = :P32_DISTRIBUTIONID;',
'  END IF;',
'EXCEPTION WHEN NO_DATA_FOUND THEN :P32_RECEIPT_INFO := NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9913200000000089
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913200000000090)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Record Approval Decision'
,p_static_id=>'record-approval-decision'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    PKG_TRUST_MGMT.record_approval(',
'        p_distribution_id => :P32_DISTRIBUTIONID,',
'        p_decision        => :P32_DECISION,',
'        p_decision_notes  => :P32_NOTES',
'    );',
'    apex_application.g_print_success_message := ''Decision recorded.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913200000000080)
,p_internal_uid=>9913200000000090
,p_created_on=>wwv_flow_imp.dz('20260806080000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806080000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913200000000091)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Execute Distribution'
,p_static_id=>'execute-distribution'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_user_id NUMBER;',
'    l_blob    BLOB;',
'    l_name    VARCHAR2(255);',
'    l_mime    VARCHAR2(100);',
'BEGIN',
'    l_user_id := FUNC_CURRENT_USER_ID;',
'    PKG_TRUST_MGMT.execute_distribution(',
'        p_distribution_id  => :P32_DISTRIBUTIONID,',
'        p_executed_by_user => l_user_id',
'    );',
'    IF :P32_PAYMENTRECEIPT IS NOT NULL THEN',
'      BEGIN',
'        SELECT blob_content, filename, mime_type',
'          INTO l_blob, l_name, l_mime',
'          FROM apex_application_temp_files',
'         WHERE name = :P32_PAYMENTRECEIPT;',
'        UPDATE DISTRIBUTION',
'           SET PaymentReceipt = l_blob,',
'               PaymentReceiptFileName = l_name,',
'               PaymentReceiptMimeType = l_mime',
'         WHERE DistributionID = :P32_DISTRIBUTIONID;',
'      EXCEPTION WHEN NO_DATA_FOUND THEN NULL; END;',
'    END IF;',
'    apex_application.g_print_success_message := ''Distribution executed (paid out).'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913200000000081)
,p_internal_uid=>9913200000000091
,p_created_on=>wwv_flow_imp.dz('20260806080000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806080000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
