,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT n.NotificationID,',
'       n.NotificationType,',
'       n.Title,',
'       n.Message,',
'       CASE WHEN n.Channel IN (''SMS'',''EMAIL'') THEN n.Channel || '' (queued)'' ELSE n.Channel END AS Channel,',
'       CASE n.IsRead WHEN 1 THEN ''Read'' ELSE ''Unread'' END AS ReadStatus,',
'       n.CreatedAt,',
'       n.RelatedTable,',
'       n.RelatedRecordID',
'  FROM NOTIFICATION n',
'  JOIN USER_ACCOUNT u ON u.UserID = n.UserID',
' WHERE UPPER(u.Username) = UPPER(:APP_USER)',
' ORDER BY n.IsRead ASC, n.CreatedAt DESC'))
,p_plug_source_type=>'NATIVE_IR'
