wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913400000000030)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load My Profile'
,p_static_id=>'load-my-profile'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_person_id   NUMBER;',
'    l_person_type VARCHAR2(15);',
'    l_name        VARCHAR2(200);',
'    l_phone       VARCHAR2(50);',
'    l_email       VARCHAR2(100);',
'    l_photo_fn    VARCHAR2(255);',
'    l_loc_addr    VARCHAR2(300);',
'    l_loc_city    VARCHAR2(100);',
'    l_loc_dist    VARCHAR2(100);',
'BEGIN',
'    SELECT Username, LinkedPersonID, LinkedPersonType',
'      INTO :P34_USERNAME, l_person_id, l_person_type',
'      FROM USER_ACCOUNT',
'     WHERE UPPER(Username) = UPPER(:APP_USER)',
'       AND IsActive = 1;',
'',
'    :P34_PERSON_TYPE := l_person_type;',
'',
'    IF l_person_type = ''TRUSTEE'' THEN',
'        SELECT Name, Phone, Email, LocationAddress, LocationCity, LocationDistrict',
'          INTO l_name, l_phone, l_email, l_loc_addr, l_loc_city, l_loc_dist',
'          FROM TRUSTEE WHERE TrusteeID = l_person_id;',
'        BEGIN',
'            EXECUTE IMMEDIATE',
'              ''SELECT ProfilePhotoFileName FROM TRUSTEE WHERE TrusteeID = :1''',
'              INTO l_photo_fn USING l_person_id;',
'        EXCEPTION WHEN OTHERS THEN l_photo_fn := NULL; END;',
'    ELSIF l_person_type = ''BENEFICIARY'' THEN',
'        SELECT Name, Phone, Email, LocationAddress, LocationCity, LocationDistrict',
'          INTO l_name, l_phone, l_email, l_loc_addr, l_loc_city, l_loc_dist',
'          FROM BENEFICIARY WHERE BeneficiaryID = l_person_id;',
'        BEGIN',
'            EXECUTE IMMEDIATE',
'              ''SELECT ProfilePhotoFileName FROM BENEFICIARY WHERE BeneficiaryID = :1''',
'              INTO l_photo_fn USING l_person_id;',
'        EXCEPTION WHEN OTHERS THEN l_photo_fn := NULL; END;',
'    ELSIF l_person_type = ''TRUSTOR'' THEN',
'        SELECT Name, Phone, Email, LocationAddress, LocationCity, LocationDistrict',
'          INTO l_name, l_phone, l_email, l_loc_addr, l_loc_city, l_loc_dist',
'          FROM TRUSTOR WHERE TrustorID = l_person_id;',
'        BEGIN',
'            EXECUTE IMMEDIATE',
'              ''SELECT ProfilePhotoFileName FROM TRUSTOR WHERE TrustorID = :1''',
'              INTO l_photo_fn USING l_person_id;',
'        EXCEPTION WHEN OTHERS THEN l_photo_fn := NULL; END;',
'    ELSIF l_person_type = ''ADMIN'' THEN',
'        l_name := ''Administrator'';',
'        l_phone := NULL;',
'        l_email := NULL;',
'        l_loc_addr := NULL; l_loc_city := NULL; l_loc_dist := NULL;',
'        BEGIN',
'            EXECUTE IMMEDIATE',
'              ''SELECT ProfilePhotoFileName FROM USER_ACCOUNT WHERE UPPER(Username) = UPPER(:1)''',
'              INTO l_photo_fn USING :APP_USER;',
'        EXCEPTION WHEN OTHERS THEN l_photo_fn := NULL; END;',
'    ELSE',
'        l_name := ''User'';',
'        l_phone := NULL;',
'        l_email := NULL;',
'        l_photo_fn := NULL;',
'        l_loc_addr := NULL; l_loc_city := NULL; l_loc_dist := NULL;',
'    END IF;',
'',
'    :P34_PERSON_NAME := l_name;',
'    :P34_PHONE := l_phone;',
'    :P34_EMAIL := l_email;',
'    :P34_LOCATIONADDRESS := l_loc_addr;',
'    :P34_LOCATIONCITY := l_loc_city;',
'    :P34_LOCATIONDISTRICT := l_loc_dist;',
'    :P34_PHOTO_FILENAME := NVL(l_photo_fn, ''(none)'');',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        :P34_USERNAME := :APP_USER;',
'        :P34_PERSON_TYPE := ''UNKNOWN'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9913400000000030
,p_created_on=>wwv_flow_imp.dz('20260806095000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806095000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913400000000031)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Contact Details'
,p_static_id=>'save-contact-details'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_person_id NUMBER;',
'BEGIN',
'    IF :P34_PERSON_TYPE NOT IN (''TRUSTEE'',''BENEFICIARY'',''TRUSTOR'') THEN',
'        apex_application.g_print_success_message :=',
'          ''Admin accounts use password change only for profile updates.'';',
'        RETURN;',
'    END IF;',
'',
'    SELECT LinkedPersonID INTO l_person_id',
'      FROM USER_ACCOUNT',
'     WHERE UPPER(Username) = UPPER(:APP_USER)',
'       AND IsActive = 1;',
'',
'    -- One UPDATE (phone/email/location). Do NOT call package COMMIT from APEX.',
'    IF :P34_PERSON_TYPE = ''TRUSTEE'' THEN',
'        UPDATE TRUSTEE',
'           SET Phone = :P34_PHONE,',
'               Email = :P34_EMAIL,',
'               LocationAddress = :P34_LOCATIONADDRESS,',
'               LocationCity = :P34_LOCATIONCITY,',
'               LocationDistrict = :P34_LOCATIONDISTRICT',
'         WHERE TrusteeID = l_person_id;',
'    ELSIF :P34_PERSON_TYPE = ''BENEFICIARY'' THEN',
'        UPDATE BENEFICIARY',
'           SET Phone = :P34_PHONE,',
'               Email = :P34_EMAIL,',
'               LocationAddress = :P34_LOCATIONADDRESS,',
'               LocationCity = :P34_LOCATIONCITY,',
'               LocationDistrict = :P34_LOCATIONDISTRICT',
'         WHERE BeneficiaryID = l_person_id;',
'    ELSE',
'        UPDATE TRUSTOR',
'           SET Phone = :P34_PHONE,',
'               Email = :P34_EMAIL,',
'               LocationAddress = :P34_LOCATIONADDRESS,',
'               LocationCity = :P34_LOCATIONCITY,',
'               LocationDistrict = :P34_LOCATIONDISTRICT',
'         WHERE TrustorID = l_person_id;',
'    END IF;',
'',
'    apex_application.g_print_success_message := ''Contact and location details saved.'';',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RAISE_APPLICATION_ERROR(-20440, ''Signed-in user account not found.'');',
'    WHEN OTHERS THEN',
'        RAISE_APPLICATION_ERROR(-20441,',
'          ''Could not save profile/location: '' || SQLERRM);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913400000000020)
,p_internal_uid=>9913400000000031
,p_created_on=>wwv_flow_imp.dz('20260806095000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806095000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913400000000032)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Profile Photo'
,p_static_id=>'save-profile-photo'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_blob      BLOB;',
'    l_mime      VARCHAR2(100);',
'    l_filename  VARCHAR2(255);',
'    l_user_id   NUMBER;',
'    l_person_id NUMBER;',
'    l_type      VARCHAR2(15);',
'    l_table     VARCHAR2(30);',
'    l_key       VARCHAR2(30);',
'    l_rows      NUMBER := 0;',
'BEGIN',
'    IF :P34_PROFILEPHOTO IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20430,',
'            ''Choose a photo file before clicking Save Photo.'');',
'    END IF;',
'',
'    BEGIN',
'        SELECT blob_content, SUBSTR(mime_type,1,100), SUBSTR(filename,1,255)',
'          INTO l_blob, l_mime, l_filename',
'          FROM apex_application_temp_files',
'         WHERE name = :P34_PROFILEPHOTO;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RAISE_APPLICATION_ERROR(-20431,',
'                ''The uploaded file is no longer available. Please pick it again.'');',
'    END;',
'',
'    BEGIN',
'        SELECT UserID, LinkedPersonID, UPPER(TRIM(LinkedPersonType))',
'          INTO l_user_id, l_person_id, l_type',
'          FROM USER_ACCOUNT',
'         WHERE UPPER(Username) = UPPER(:APP_USER)',
'           AND IsActive = 1;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
'            RAISE_APPLICATION_ERROR(-20432,',
'                ''No active user account found for the signed-in user.'');',
'    END;',
'',
'    IF l_person_id IS NOT NULL AND l_type = ''TRUSTEE'' THEN',
'        l_table := ''TRUSTEE'';     l_key := ''TrusteeID'';',
'    ELSIF l_person_id IS NOT NULL AND l_type = ''BENEFICIARY'' THEN',
'        l_table := ''BENEFICIARY''; l_key := ''BeneficiaryID'';',
'    ELSIF l_person_id IS NOT NULL AND l_type = ''TRUSTOR'' THEN',
'        l_table := ''TRUSTOR'';     l_key := ''TrustorID'';',
'    END IF;',
'',
'    IF l_table IS NOT NULL THEN',
'        EXECUTE IMMEDIATE',
'            ''UPDATE '' || l_table || '' SET ProfilePhoto = :1,''',
'            || '' ProfilePhotoMimeType = :2, ProfilePhotoFileName = :3''',
'            || '' WHERE '' || l_key || '' = :4''',
'            USING l_blob, l_mime, l_filename, l_person_id;',
'        l_rows := SQL%ROWCOUNT;',
'    END IF;',
'',
'    IF l_rows = 0 THEN',
'        EXECUTE IMMEDIATE',
'            ''UPDATE USER_ACCOUNT SET ProfilePhoto = :1,''',
'            || '' ProfilePhotoMimeType = :2, ProfilePhotoFileName = :3''',
'            || '' WHERE UserID = :4''',
'            USING l_blob, l_mime, l_filename, l_user_id;',
'        l_rows  := SQL%ROWCOUNT;',
'        l_table := ''USER_ACCOUNT'';',
'    END IF;',
'',
'    IF l_rows = 0 THEN',
'        RAISE_APPLICATION_ERROR(-20433,',
'            ''Could not store the profile photo for this account.'');',
'    END IF;',
'',
'    BEGIN',
'        INSERT INTO AUDIT_LOG (',
'            LogID, UserID, ActionType, ActionDescription, TableAffected, RecordID',
'        ) VALUES (',
'            SEQ_AUDIT_LOG.NEXTVAL, l_user_id, ''PROFILE_PHOTO_UPDATED'',',
'            ''User updated own profile photo'', l_table,',
'            CASE WHEN l_table = ''USER_ACCOUNT'' THEN l_user_id ELSE l_person_id END',
'        );',
'    EXCEPTION',
'        WHEN OTHERS THEN NULL;',
'    END;',
'',
'    DELETE FROM apex_application_temp_files WHERE name = :P34_PROFILEPHOTO;',
'',
'    :P34_PROFILEPHOTO   := NULL;',
'    :P34_PHOTO_FILENAME := l_filename;',
'    :G_AVATAR_TS := TO_CHAR(SYSTIMESTAMP, ''YYYYMMDDHH24MISSFF3'');',
'    :G_USER_AVATAR_URL :=',
'           ''f?p='' || :APP_ID || '':0:'' || :APP_SESSION',
'        || '':APPLICATION_PROCESS=GET_PROFILE_PHOTO:::G_AVATAR_TS,''',
'        || :G_AVATAR_TS;',
'    apex_application.g_print_success_message := ''Photo updated. Your navbar avatar will refresh on the next page.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913400000000022)
,p_internal_uid=>9913400000000032
,p_created_on=>wwv_flow_imp.dz('20260806095000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807140000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9913400000000033)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Change My Password'
,p_static_id=>'change-my-password'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P34_NEW_PASSWORD IS NULL OR :P34_CONFIRM_PASSWORD IS NULL THEN',
'        RAISE_APPLICATION_ERROR(-20001, ''Enter and confirm the new password.'');',
'    END IF;',
'    IF :P34_NEW_PASSWORD != :P34_CONFIRM_PASSWORD THEN',
'        RAISE_APPLICATION_ERROR(-20002, ''New password and confirmation do not match.'');',
'    END IF;',
'    PKG_TRUST_MGMT.update_my_password(:P34_CURRENT_PASSWORD, :P34_NEW_PASSWORD);',
'    :P34_CURRENT_PASSWORD := NULL;',
'    :P34_NEW_PASSWORD := NULL;',
'    :P34_CONFIRM_PASSWORD := NULL;',
'    apex_application.g_print_success_message := ''Password changed successfully.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9913400000000021)
,p_internal_uid=>9913400000000033
,p_created_on=>wwv_flow_imp.dz('20260806095000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806095000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
end;
