,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Trustee'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  INSERT INTO TRUST_TRUSTEE (TrustID, TrusteeID, DateAssigned)',
'  VALUES (:P37_TRUSTID, :P37_TRUSTEEID, SYSDATE);',
'  :P37_TRUSTEEID := NULL;',
'  apex_application.g_print_success_message := ''Trustee assigned.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9914300000000022)
,p_internal_uid=>9914300000000050
,p_created_on=>wwv_flow_imp.dz('20260806131000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806131000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
