wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9914300000000051)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Assign Beneficiary'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_sum NUMBER;',
'BEGIN',
'  IF :P37_SHAREPERCENTAGE IS NULL OR :P37_SHAREPERCENTAGE <= 0 OR :P37_SHAREPERCENTAGE > 100 THEN',
'    RAISE_APPLICATION_ERROR(-20010, ''Share % must be between 0 and 100.'');',
'  END IF;',
'  SELECT NVL(SUM(SharePercentage),0) INTO l_sum',
'    FROM TRUST_BENEFICIARY WHERE TrustID = :P37_TRUSTID;',
'  IF l_sum + :P37_SHAREPERCENTAGE > 100 THEN',
'    RAISE_APPLICATION_ERROR(-20011,',
'      ''Beneficiary shares on this trust would total '' ||',
'      TO_CHAR(l_sum + :P37_SHAREPERCENTAGE) ||',
'      ''%. Current total is '' || TO_CHAR(l_sum) ||',
'      ''%. Shares must not exceed 100%.'');',
'  END IF;',
'  INSERT INTO TRUST_BENEFICIARY (TrustID, BeneficiaryID, SharePercentage)',
'  VALUES (:P37_TRUSTID, :P37_BENEFICIARYID, :P37_SHAREPERCENTAGE);',
'  SELECT NVL(SUM(SharePercentage),0) INTO l_sum',
'    FROM TRUST_BENEFICIARY WHERE TrustID = :P37_TRUSTID;',
'  :P37_BENEFICIARYID := NULL;',
'  :P37_SHAREPERCENTAGE := NULL;',
'  IF l_sum < 100 THEN',
'    apex_application.g_print_success_message :=',
'      ''Beneficiary assigned. Share total is now '' || l_sum || ''% (must reach 100% before distributions).'';',
'  ELSE',
'    apex_application.g_print_success_message := ''Beneficiary assigned. Shares total 100%.'';',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9914300000000043)
,p_internal_uid=>9914300000000051
,p_created_on=>wwv_flow_imp.dz('20260806131000Z')
,p_updated_on=>wwv_flow_imp.dz('20260806131000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
