,p_plug_name=>'Inbox'
,p_static_id=>'messages-inbox'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT m.MessageID,',
'       CASE WHEN m.ReceiverID = FUNC_CURRENT_USER_ID THEN ''Inbox'' ELSE ''Sent'' END AS Folder,',
'       s.Username AS Sender,',
'       r.Username AS Receiver,',
'       m.Subject,',
'       CASE m.IsRead WHEN 1 THEN ''Read'' ELSE ''Unread'' END AS ReadStatus,',
'       m.SentDate,',
'       t.TrustName',
'  FROM MESSAGE m',
'  JOIN USER_ACCOUNT s ON s.UserID = m.SenderID',
'  JOIN USER_ACCOUNT r ON r.UserID = m.ReceiverID',
'  LEFT JOIN TRUST t ON t.TrustID = m.RelatedTrustID',
' WHERE (m.ReceiverID = FUNC_CURRENT_USER_ID AND NVL(m.IsDeletedByReceiver,0) = 0)',
'    OR (m.SenderID = FUNC_CURRENT_USER_ID AND NVL(m.IsDeletedBySender,0) = 0)',
' ORDER BY m.SentDate DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_ai_enabled=>false
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
