wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9915000000004330)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load message for view'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P43_MESSAGEID IS NOT NULL THEN',
'    SELECT ReceiverID, Subject, MessageText, RelatedTrustID',
'      INTO :P43_RECEIVERID, :P43_SUBJECT, :P43_MESSAGETEXT, :P43_RELATEDTRUSTID',
'      FROM MESSAGE',
'     WHERE MessageID = :P43_MESSAGEID',
'       AND (ReceiverID = FUNC_CURRENT_USER_ID OR SenderID = FUNC_CURRENT_USER_ID);',
'    UPDATE MESSAGE',
'       SET IsRead = 1',
'     WHERE MessageID = :P43_MESSAGEID',
'       AND ReceiverID = FUNC_CURRENT_USER_ID',
'       AND NVL(IsRead,0) = 0;',
'  END IF;',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN',
'    NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9915000000004330
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9915000000004331)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Message'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_id NUMBER;',
'BEGIN',
'  SELECT SEQ_MESSAGE.NEXTVAL INTO l_id FROM DUAL;',
'  INSERT INTO MESSAGE (',
'    MessageID, SenderID, ReceiverID, Subject, MessageText,',
'    SentDate, IsRead, IsDeletedBySender, IsDeletedByReceiver, RelatedTrustID',
'  ) VALUES (',
'    l_id, FUNC_CURRENT_USER_ID, :P43_RECEIVERID, :P43_SUBJECT, :P43_MESSAGETEXT,',
'    SYSTIMESTAMP, 0, 0, 0, :P43_RELATEDTRUSTID',
'  );',
'  apex_application.g_print_success_message := ''Message sent.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9915000000004311)
,p_internal_uid=>9915000000004331
