,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>20
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT tk.TaskID, tk.TaskTitle, tk.TaskType, tk.Priority, tk.Status,',
'       tk.DueDate, t.TrustName,',
'       a.Username AS AssignedToUser,',
'       c.Username AS CreatedByUser,',
'       tk.CreatedDate',
'  FROM TASK tk',
'  LEFT JOIN TRUST t ON t.TrustID = tk.TrustID',
'  JOIN USER_ACCOUNT a ON a.UserID = tk.AssignedTo',
'  JOIN USER_ACCOUNT c ON c.UserID = tk.CreatedBy',
' WHERE tk.AssignedTo = FUNC_CURRENT_USER_ID',
'    OR tk.CreatedBy = FUNC_CURRENT_USER_ID',
'    OR EXISTS (',
'         SELECT 1 FROM USER_ACCOUNT u',
'          JOIN ROLE r ON r.RoleID = u.RoleID',
'         WHERE UPPER(u.Username) = UPPER(:APP_USER)',
'           AND r.RoleName = ''ADMIN'')',
' ORDER BY CASE tk.Status WHEN ''COMPLETED'' THEN 2 WHEN ''CANCELLED'' THEN 3 ELSE 1 END,',
'          CASE tk.Priority WHEN ''URGENT'' THEN 1 WHEN ''HIGH'' THEN 2 WHEN ''MEDIUM'' THEN 3 ELSE 4 END,',
'          tk.DueDate NULLS LAST'))
,p_plug_source_type=>'NATIVE_IR'
,p_ai_enabled=>false
