wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9915000000004530)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  IF :P45_TASKID IS NOT NULL THEN',
'    SELECT TaskTitle, TaskDescription, TrustID, AssignedTo, TaskType,',
'           Priority, Status, DueDate',
'      INTO :P45_TASKTITLE, :P45_TASKDESCRIPTION, :P45_TRUSTID, :P45_ASSIGNEDTO,',
'           :P45_TASKTYPE, :P45_PRIORITY, :P45_STATUS, :P45_DUEDATE',
'      FROM TASK WHERE TaskID = :P45_TASKID;',
'  ELSIF :P45_ASSIGNEDTO IS NULL THEN',
'    :P45_ASSIGNEDTO := FUNC_CURRENT_USER_ID;',
'    :P45_STATUS := NVL(:P45_STATUS, ''PENDING'');',
'  END IF;',
'EXCEPTION',
'  WHEN NO_DATA_FOUND THEN NULL;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>9915000000004530
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9915000000004531)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  l_id NUMBER;',
'BEGIN',
'  IF :P45_TASKID IS NULL THEN',
'    SELECT SEQ_TASK.NEXTVAL INTO l_id FROM DUAL;',
'    INSERT INTO TASK (',
'      TaskID, TrustID, AssignedTo, CreatedBy, TaskTitle, TaskDescription,',
'      TaskType, Priority, Status, DueDate, CreatedDate, UpdatedDate',
'    ) VALUES (',
'      l_id, :P45_TRUSTID, :P45_ASSIGNEDTO, FUNC_CURRENT_USER_ID,',
'      :P45_TASKTITLE, :P45_TASKDESCRIPTION, :P45_TASKTYPE, :P45_PRIORITY,',
'      NVL(:P45_STATUS,''PENDING''),',
'      CASE WHEN :P45_DUEDATE IS NULL THEN NULL ELSE TO_DATE(:P45_DUEDATE, :APP_DATE_FORMAT) END,',
'      SYSTIMESTAMP, SYSTIMESTAMP',
'    );',
'    :P45_TASKID := l_id;',
'    apex_application.g_print_success_message := ''Task created.'';',
'  ELSE',
'    UPDATE TASK SET',
'      TrustID = :P45_TRUSTID,',
'      AssignedTo = :P45_ASSIGNEDTO,',
'      TaskTitle = :P45_TASKTITLE,',
'      TaskDescription = :P45_TASKDESCRIPTION,',
'      TaskType = :P45_TASKTYPE,',
'      Priority = :P45_PRIORITY,',
'      Status = NVL(:P45_STATUS,''PENDING''),',
'      DueDate = CASE WHEN :P45_DUEDATE IS NULL THEN NULL ELSE TO_DATE(:P45_DUEDATE, :APP_DATE_FORMAT) END,',
'      UpdatedDate = SYSTIMESTAMP',
'    WHERE TaskID = :P45_TASKID;',
'    apex_application.g_print_success_message := ''Task updated.'';',
'  END IF;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9915000000004511)
,p_internal_uid=>9915000000004531
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9915000000004532)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Complete Task'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  UPDATE TASK SET',
'    Status = ''COMPLETED'',',
'    CompletedDate = SYSDATE,',
'    UpdatedDate = SYSTIMESTAMP',
'  WHERE TaskID = :P45_TASKID;',
'  apex_application.g_print_success_message := ''Task marked complete.'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(9915000000004512)
,p_internal_uid=>9915000000004532
,p_created_on=>wwv_flow_imp.dz('20260807120000Z')
,p_updated_on=>wwv_flow_imp.dz('20260807120000Z')
,p_created_by=>'PRIMO'
,p_updated_by=>'PRIMO'
);
end;
